pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 newMinSum, address newLogFile) internal {
        try c.Initialized() {} catch { return; }
        uint256 oldMinSum;
        try c.MinSum() returns (uint256 __r) { oldMinSum = __r; } catch { return; }
        bool revertedMin;
        try c.SetMinSum(newMinSum) {
            revertedMin = false;
        } catch {
            revertedMin = true;
        }
        bool revertedLog;
        try c.SetLogFile(newLogFile) {
            revertedLog = false;
        } catch {
            revertedLog = true;
        }
        assertTrue(revertedMin && revertedLog && c.MinSum() == oldMinSum);
    }

    function testFuzz_run(uint256 newMinSum, address newLogFile) public {
        vm.assume(newLogFile.code.length == 0 && uint160(newLogFile) > 0xffff && newLogFile != address(this) && newLogFile != address(c) && newLogFile != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && newLogFile != 0x000000000000000000636F6e736F6c652e6c6f67 && newLogFile != 0x4e59b44847b379578588920cA78FbF26c0B4956C && newLogFile != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(newMinSum, newLogFile);
    }

    receive() external payable {}
}
